/**
 * @name Path traversal in file operations
 * @description User-controlled file paths without validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that could contain user-controlled paths
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["filename", "key", "path", "filepath", "destination", "source_filename", "dest_filename"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system operations
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"

/**
 * @name Command injection in s3transfer
 * @description Executing system commands with user-controlled input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["filename", "key", "bucket", "path", "extra_args"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Sensitive information in logs
 * @description Logging sensitive information like credentials or keys can lead to information disclosure
 * @kind path-problem
 * @problem.severity warning
 * @id py/s3transfer-sensitive-logging
 * @tags security
 *        external/cwe/cwe-532
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SensitiveLoggingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in [
        "secret", "password", "token", "key", "credential", "auth",
        "access_key", "secret_key", "session_token", "extra_args"
      ]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical", "log"]).getACall() and
      sink = call.getArg(_)
    )
  }
}

module SensitiveLoggingFlow = TaintTracking::Global<SensitiveLoggingConfig>;
import SensitiveLoggingFlow::PathGraph

from SensitiveLoggingFlow::PathNode source, SensitiveLoggingFlow::PathNode sink
where SensitiveLoggingFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Sensitive information from $@ may be logged.", source.getNode(), "parameter"

/**
 * @name S3 key manipulation vulnerability
 * @description S3 keys constructed from user input without validation may allow unauthorized access
 * @kind path-problem
 * @problem.severity high
 * @id py/s3transfer-s3-key-manipulation
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module S3KeyManipulationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["key", "s3_key", "object_key", "prefix"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["put_object", "get_object", "head_object", "delete_object", "copy_object"] or
        call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["upload_file", "download_file", "copy"]
      ) and
      sink = call.getArg(_)
    )
  }
}

module S3KeyManipulationFlow = TaintTracking::Global<S3KeyManipulationConfig>;
import S3KeyManipulationFlow::PathGraph

from S3KeyManipulationFlow::PathNode source, S3KeyManipulationFlow::PathNode sink
where S3KeyManipulationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "S3 key manipulation from $@.", source.getNode(), "user-controlled input"

/**
 * @name Unsafe URL construction in s3transfer
 * @description Constructing URLs with user-controlled input without validation
 * @kind path-problem
 * @problem.severity warning
 * @id py/s3transfer-unsafe-url
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeUrlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["url", "endpoint", "bucket", "key"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() or
        call = API::moduleImport("requests").getMember(["get", "post", "put", "delete"]).getACall() or
        call = API::moduleImport("http").getMember("client").getMember("HTTPConnection").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module UnsafeUrlFlow = TaintTracking::Global<UnsafeUrlConfig>;
import UnsafeUrlFlow::PathGraph

from UnsafeUrlFlow::PathNode source, UnsafeUrlFlow::PathNode sink
where UnsafeUrlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe URL construction from $@.", source.getNode(), "user input"
